<article class="product-card" data-product data-id="<?= e($product['id']) ?>" data-category="<?= e($product['category_id']) ?>" data-name="<?= e($product['name']) ?>" data-sku="<?= e($product['sku']) ?>" data-unit="<?= e($product['unit']) ?>"><div class="product-image"><?php if($product['badge'])component('badge',['label'=>$product['badge']]);?><img src="<?= e($product['image_url']??asset('images/'.$product['image'])) ?>" alt="<?= e($product['image_alt']??'Ilustración de referencia: '.$product['name']) ?>" loading="lazy" width="280" height="220"></div><div class="product-body"><p class="product-category"><?= e($product['category']) ?></p><h3><?= e($product['name']) ?></h3><p class="product-unit"><?= e($product['unit']) ?><?= ($isDemo??true)?' · Producto demo':'' ?></p><div class="product-bottom"><span>Precio por cotizar</span><?php if($isDemo??true):?><button type="button" class="add-product" aria-label="Agregar <?= e($product['name']) ?> a la lista de demostración" disabled><?= icon('plus') ?></button><?php else:?><a class="add-product" href="<?= e($product['quote_href']) ?>" aria-label="Solicitar cotización de <?= e($product['name']) ?>"><?= icon('arrow') ?></a><?php endif?></div></div></article>
